 public function approveEvidence(string $reference,string $sha):array|WP_Error {
  if(get_current_user_id()<1||!current_user_can('manage_digiforge_pod'))return self::error('operator_required');
  $transaction=false;try{$m=$this->mapping($reference,$sha);$record=['version'=>'orthographic-digital-mockup-v1','evidence_sha256'=>$sha,'approved_by'=>get_current_user_id(),'approved_at'=>gmdate(DATE_ATOM),'supplier_certified'=>false,'external_execution_authorized'=>false];$record['sha256']=hash('sha256',Validator::canonicalJson($record));global $wpdb;$name='df_customer_mockup_'.$sha;$wpdb->last_error='';if($wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$name))!==null)return self::error('immutable_replay');$engines=$wpdb->get_col($wpdb->prepare('SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN (%s,%s)',$wpdb->options,Tables::audit_log()));if(count($engines)!==2||array_filter($engines,static fn($e)=>strtoupper((string)$e)!=='INNODB')||$wpdb->query('START TRANSACTION')===false)return self::error('transactional_storage_required');$transaction=true;$ok=$wpdb->insert($wpdb->options,['option_name'=>$name,'option_value'=>Validator::canonicalJson($record),'autoload'=>'no']);if($ok!==1||!Logger::write('customer_mockup_mapping_approved',['sha256'=>$record['sha256']],'customer_mockup',$sha)){$wpdb->query('ROLLBACK');return self::error('audit_uncertain');}if($wpdb->query('COMMIT')===false){$wpdb->query('ROLLBACK');return self::error('commit_uncertain');}$transaction=false;return $record;}catch(\Throwable){return self::error('mapping_evidence_required');}finally{if($transaction)$wpdb->query('ROLLBACK');}
 }
 public function compose(array $render,array $artifact,string $reference,string $sha,int $customer):array|WP_Error {
  try{$m=$this->mapping($reference,$sha);global $wpdb;$wpdb->last_error='';$raw=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s','df_customer_mockup_'.$sha));if($wpdb->last_error!==''||!is_string($raw)||strlen($raw)>65536)return self::error('approved_mapping_required');$approved=json_decode($raw,true);$h=$approved['sha256']??null;unset($approved['sha256']);if(!is_string($h)||!hash_equals($h,hash('sha256',Validator::canonicalJson($approved)))||$approved['evidence_sha256']!==$sha||$approved['approved_by']===$customer||!user_can($approved['approved_by'],'manage_digiforge_pod'))return self::error('independent_mapping_required');$wpdb->last_error='';$rows=$wpdb->get_col($wpdb->prepare('SELECT context FROM '.Tables::audit_log().' WHERE event_type=%s AND object_type=%s AND object_id=%s','customer_mockup_mapping_approved','customer_mockup',$sha));if($wpdb->last_error!==''||!is_array($rows)||!array_filter($rows,static fn($r)=>(json_decode($r,true)['sha256']??null)===$h))return self::error('audit_required');if($m['render_id']!==(int)$render['id']||$m['render_evidence_hash']!==$render['evidence_hash']||$m['template_sha256']!==$render['template_sha256']||$m['order_id']!==(int)$render['order_id']||$m['panel']!==$artifact['position']||$artifact['mime']!=='image/png')return self::error('render_mapping_mismatch');$art=base64_decode($artifact['content_base64'],true);if(!is_string($art)||hash('sha256',$art)!==$artifact['sha256'])throw new \InvalidArgumentException();$overlay=RasterArtworkCodec::decode($art);$base=(new RenderArtifactStore())->verify($m['base_artifact']);if($base instanceof WP_Error)return $base;$basePath=AssetStorage::absolutePath($base['storage_reference']);$pixels=RasterArtworkCodec::decode(file_get_contents($basePath));$rect=$m['placement'];if($rect['width']*$overlay['height_px']!==$rect['height']*$overlay['width_px'])return self::error('unsupported_projection');$rgba=$pixels['rgba'];for($y=0;$y<$rect['height'];$y++)for($x=0;$x<$rect['width'];$x++){$s=(intdiv($y*$overlay['height_px'],$rect['height'])*$overlay['width_px']+intdiv($x*$overlay['width_px'],$rect['width']))*4;$d=(($y+$rect['y'])*$pixels['width_px']+$x+$rect['x'])*4;$a=ord($overlay['rgba'][$s+3]);$ba=ord($rgba[$d+3]);$den=$a*255+$ba*(255-$a);for($c=0;$c<3;$c++)$rgba[$d+$c]=chr($den===0?0:intdiv(ord($overlay['rgba'][$s+$c])*$a*255+ord($rgba[$d+$c])*$ba*(255-$a)+intdiv($den,2),$den));$rgba[$d+3]=chr(intdiv($den+127,255));}$png=RasterArtworkCodec::encode($pixels['width_px'],$pixels['height_px'],$rgba);return ['content_base64'=>base64_encode($png),'mime'=>'image/png','sha256'=>hash('sha256',$png),'artwork_sha256'=>$artifact['sha256'],'variant_key'=>$m['provider_id'].':'.$m['variant_id'],'width_px'=>$pixels['width_px'],'height_px'=>$pixels['height_px'],'evidence_kind'=>$m['evidence_kind'],'label'=>$m['evidence_kind']==='SYNTHETIC_TEST_ONLY'?'Synthetic test-only digital mockup — no commercial certification':'Digital product mockup — not a physical print guarantee','projection'=>'APPROVED_ORTHOGRAPHIC_RECTANGLE','supplier_certified'=>false];
  }catch(\Throwable){return self::error('safe_mockup_unavailable');}
 }
 private function mapping(string $ref,string $sha):array {
  $repo=new CustomerEditorRepository();$body=$repo->document($ref,$sha,'pod-mockup-evidence');$m=json_decode($body,true,16,JSON_THROW_ON_ERROR);$keys=['schema','shop_key','order_id','render_id','render_evidence_hash','template_sha256','provider_blueprint_id','provider_id','variant_id','panel','print_area_sha256','projection','base_artifact','placement','rights_reference','rights_sha256','evidence_kind'];if(!is_array($m)||count($m)!==count($keys)||array_diff(array_keys($m),$keys)||$m['schema']!==1||$m['shop_key']!=='personalized_pod'||$m['projection']!=='ORTHOGRAPHIC_RECTANGLE_V1'||!in_array($m['evidence_kind'],['OWNER_SUPPLIED','SYNTHETIC_TEST_ONLY'],true))throw new \InvalidArgumentException();foreach(['order_id','render_id','provider_blueprint_id','provider_id','variant_id']as $k)if(!is_int($m[$k])||$m[$k]<1)throw new \InvalidArgumentException();global $wpdb;$wpdb->last_error='';$render=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::pod_render_evidence().' WHERE id=%d',$m['render_id']),ARRAY_A);if($wpdb->last_error!==''||!is_array($render)||(int)$render['order_id']!==$m['order_id']||$render['evidence_hash']!==$m['render_evidence_hash'])throw new \InvalidArgumentException();$template=(new RenderArtifactVerifier())->certifiedTemplate($render);if($template instanceof WP_Error)throw new \InvalidArgumentException();$wpdb->last_error='';$variant=$wpdb->get_var($wpdb->prepare('SELECT provider_variant_key FROM '.Tables::pod_mappings().' WHERE id=%d',(int)$render['provider_mapping_id']));if($wpdb->last_error!==''||$variant!==$m['provider_id'].':'.$m['variant_id']||$template['provider_blueprint_id']!==$m['provider_blueprint_id']||$template['provider_id']!==$m['provider_id']||$template['fingerprint']!==$m['template_sha256'])throw new \InvalidArgumentException();$area=null;foreach($template['print_areas']as $candidate)if($candidate['position']===$m['panel'])$area=$candidate;if($area===null||hash('sha256',Validator::canonicalJson($area))!==$m['print_area_sha256'])throw new \InvalidArgumentException();$base=(new RenderArtifactStore())->verify($m['base_artifact']);if($base instanceof WP_Error||$base['mime']!=='image/png'||!str_contains($base['storage_reference'],'/shop-personalized_pod/'))throw new \InvalidArgumentException();$r=$m['placement'];if(!is_array($r)||count($r)!==4||array_diff(array_keys($r),['x','y','width','height']))throw new \InvalidArgumentException();foreach($r as $n)if(!is_int($n)||$n<0||$n>10000)throw new \InvalidArgumentException();if($r['width']<1||$r['height']<1||$r['width']*$r['height']>RasterArtworkCodec::MAX_PIXELS||$r['x']+$r['width']>$base['width_px']||$r['y']+$r['height']>$base['height_px'])throw new \InvalidArgumentException();$rights=json_decode($repo->document($m['rights_reference'],$m['rights_sha256'],'pod-mockup-rights'),true,16,JSON_THROW_ON_ERROR);$expected=['schema'=>1,'shop_key'=>'personalized_pod','base_sha256'=>$base['sha256'],'local_digital_preview_display_permitted'=>true,'evidence_kind'=>$m['evidence_kind']];if(Validator::canonicalJson($rights)!==Validator::canonicalJson($expected))throw new \InvalidArgumentException();return $m;
 }
 private static function error(string $code):WP_Error {return new WP_Error('customer_mockup_'.$code,'An exact approved product image, supplier geometry and digital mapping are required.',['status'=>409,'supplier_certified'=>false,'external_execution_authorized'=>false]);}
}
